describe("WeightBasedShippingCalculator", () => {
  const brackets: WeightBracket[] = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 1000, costCents: 600 },
    { upToGrams: 5000, costCents: 1200 },
  ];

  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: 100.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            99.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weight on products)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([lineNoWeight("a", 2)], 1000),
      ).toBe(0);
    });

    it("selects the first bracket that covers the weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 400g → first bracket (up to 500g), cost 300
      expect(calc.computeShippingCents([line("a", 400, 1)], 1000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 500g → first bracket boundary
      expect(calc.computeShippingCents([line("a", 500, 1)], 1000)).toBe(300);
      // 501g → second bracket
      expect(calc.computeShippingCents([line("a", 501, 1)], 1000)).toBe(600);
      // 1000g → second bracket boundary
      expect(calc.computeShippingCents([line("a", 1000, 1)], 1000)).toBe(600);
      // 1001g → third bracket
      expect(calc.computeShippingCents([line("a", 1001, 1)], 1000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      // 6000g > 5000g max bracket
      expect(calc.computeShippingCents([line("a", 6000, 1)], 1000)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflowCostCents", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 6000g > 5000g max bracket, falls back to last bracket cost 1200
      expect(calc.computeShippingCents([line("a", 6000, 1)], 1000)).toBe(1200);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered: WeightBracket[] = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ];
      const calc = new WeightBasedShippingCalculator(unordered);
      expect(calc.computeShippingCents([line("a", 400, 1)], 1000)).toBe(300);
    });

    it("accounts for quantity in weight calculation", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 3 items at 200g = 600g → second bracket
      expect(calc.computeShippingCents([line("a", 200, 3)], 1000)).toBe(600);
    });
  });
});

