  unitPriceCents,
  ...opts,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding the same product twice", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("a", 1000), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
      expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unit price", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", -100), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity for existing product", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 5)).toThrow(
        "Product nonexistent is not in the cart",
      );
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of cart lines", () => {
      const cart = new Cart();
      const p = product("a", 1000);
      cart.add(p, 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0].product.id).toBe("a");
      expect(snap[0].quantity).toBe(2);

      // Mutating snapshot should not affect cart
      (snap[0] as { quantity: number }).quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals – pricing pipeline", () => {
